      "campo": "resolucao.antes.formulas",
      "depois": [
        "lar (família) → mando, desigualdade, necessidade",
        "polis → persuasão, igualdade, liberdade",
        "pré-político = fora da política, e não 'pouco político'"
      ],
      "motivo": "Troca o sinal '=' por setas e acrescenta a regra que evita a armadilha principal."
    },
    {
      "campo": "resolucao.antes.simbolos",
